      </Flex>
      <br />
      <Button
        variant="plain"
        {...(!isUploading && { 'aria-label': 'Upload' })}
        onClick={() => setIsUploading(!isUploading)}
        icon={<UploadIcon />}
        {...uploadingProps}
      />
      <br />
      <br />
      <Button variant="link" isInline onClick={() => setIsInlineLoading(!isInlineLoading)} {...inlineLoadingProps}>
        {isInlineLoading ? 'Pause loading logs' : 'Resume loading logs'}
      </Button>
    </>
  );
};

import { Fragment } from 'react';
import { Button, KeyTypes } from '@patternfly/react-core';

const handleKeydown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
  const { key } = event;
  const isEnterKey: boolean = key === KeyTypes.Enter;
  const isEnterOrSpaceKey: boolean = isEnterKey || key === KeyTypes.Space;

  if (isEnterOrSpaceKey) {
    event.preventDefault();
    alert(`${isEnterKey ? 'Enter' : 'Space'} key default behavior stopped by onKeyDown`);
  }
};

