import "./reactFlowOverrides.css";

const PFCardNode = memo(
  ({
    data,
    isConnectable,
  }: {
    data: any;
    isConnectable: boolean;
  }) => {
    return (
      <>
        <Handle
          type="target"
          position={Position.Left}
          isConnectable={isConnectable}
          style={{ background: "#555" }}
        />
        <div style={{ minWidth: "300px", maxWidth: "400px" }}>
          <Card isFullHeight>
            <CardTitle>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <Title headingLevel="h4" size="lg">
                  {data.title}
                </Title>
                <Badge isRead>{data.status}</Badge>
              </div>
            </CardTitle>
            <CardBody>
              <p>
                {data.description}
              </p>
              <DescriptionList aria-label={`${data.title} details`}>
                {data.details.map((detail, index) => (
                  <DescriptionListGroup key={index}>
                    <DescriptionListTerm>{detail.term}</DescriptionListTerm>
                    <DescriptionListDescription>
                      {detail.description}
                    </DescriptionListDescription>
                  </DescriptionListGroup>
                ))}
              </DescriptionList>
            </CardBody>
            {data.actionText && (
              <>
                <Divider />
                <CardFooter>
                  <Button
                    variant="link"
                    onClick={() => {
                      // Call the original action if provided
                      data.onAction?.();
                    }}
                    style={{ padding: 0 }}
                  >
                    {data.actionText}
                  </Button>
                </CardFooter>
              </>
            )}
          </Card>
        </div>
        <Handle
          type="source"
          position={Position.Right}
          isConnectable={isConnectable}
          style={{ background: "#555" }}
        />
      </>
    );
  }
);

const initialNodes = [
  {
    id: "0",
    type: "pfCard",
    data: {
      title: "Application Service",
      status: "Running",
      description:
        "A microservice handling user authentication and authorization.",
      details: [
